SELECT a.*, buyer.name AS buyer_name, seller.name AS seller_name
FROM schema_verify.financing_application a
LEFT JOIN schema_graph.enterprise buyer ON buyer.id = a.buyer_enterprise_id
LEFT JOIN schema_graph.enterprise seller ON seller.id = a.seller_enterprise_id

    AND a.status = #{status}
    AND a.submitted_by = #{submittedBy}
    AND a.enterprise_id = #{enterpriseId}

        AND (a.app_no ILIKE '%' || #{keyword} || '%'
            OR buyer.name ILIKE '%' || #{keyword} || '%'
            OR seller.name ILIKE '%' || #{keyword} || '%')


ORDER BY a.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM schema_verify.financing_application a
LEFT JOIN schema_graph.enterprise buyer ON buyer.id = a.buyer_enterprise_id
LEFT JOIN schema_graph.enterprise seller ON seller.id = a.seller_enterprise_id

    AND a.status = #{status}
