UPDATE schema_verify.financing_application
business_type = #{businessType}, financing_amount = #{financingAmount}, buyer_enterprise_id = #{buyerEnterpriseId}, seller_enterprise_id = #{sellerEnterpriseId}, status = #{status}, current_handler = #{currentHandler}, submitted_at = #{submittedAt}, approved_at = #{approvedAt}, version = #{version}, updated_at = NOW(),
WHERE id = #{id}

